<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/bootstrap.php';
require_once dirname(__DIR__,2).'/app/LeadReplyService.php';
require_once dirname(__DIR__,2).'/app/BrevoSettings.php';
header('Cache-Control: private, no-store');header('X-Robots-Tag: noindex, nofollow');
if(isset($_SESSION['admin'])&&time()-(int)($_SESSION['last_seen']??0)>1800)unset($_SESSION['admin']);
if(empty($_SESSION['admin'])){http_response_code(403);exit('Inicia sesión desde el portal.');}
$_SESSION['last_seen']=time();
$lead=filter_var($_GET['lead']??null,FILTER_VALIDATE_INT);if(!$lead||$lead<1){http_response_code(404);exit('Solicitud no encontrada.');}
$q=db()->prepare('SELECT * FROM leads WHERE id=?');$q->execute([$lead]);$request=$q->fetch(PDO::FETCH_ASSOC);if(!$request){http_response_code(404);exit('Solicitud no encontrada.');}
$service=new LeadReplyService(db());$error='';$notice='';$row=null;$history=[];$settings=[];$simulated=!empty($config['local_test']);
try{
    $settings=$simulated?['enabled'=>true,'api_key'=>'synthetic-transport-only','sender_email'=>'respuestas@example.invalid','sender_name'=>'Explorando Lugares · Pruebas','reply_to'=>'ayuda@example.invalid']:BrevoSettings::load(private_storage_path('brevo'),(string)$config['app_key']);
    $operation=is_string($_GET['operation']??null)?$_GET['operation']:'';
    if($operation!==''){$row=$service->find($operation,$lead);if(!$row){http_response_code(404);exit('Respuesta no encontrada.');}}
    if($_SERVER['REQUEST_METHOD']==='POST'){
        csrf();$actor=(!empty($_SESSION['admin_account_id'])?'account:'.(int)$_SESSION['admin_account_id']:(string)($_SESSION['admin_user']??$config['admin_user']??'legacy-admin'));$action=$_POST['action']??'';
        if($action==='prepare'){
            $id=is_string($_POST['operation']??null)&&$_POST['operation']!==''?$_POST['operation']:null;
            if($id===null&&$service->history($lead)&&($_POST['new_reply_confirm']??'')!=='1')throw new RuntimeException('Ya hay respuestas registradas. Confirma que quieres preparar una respuesta adicional.');
            $row=$service->prepare($lead,$_POST,$settings,$actor,$id);
            header('Location: responder-solicitud.php?'.http_build_query(['lead'=>$lead,'operation'=>$row['id']]),true,303);exit;
        }elseif($action==='reconcile'){
            if(($_POST['confirm_reconcile']??'')!=='1')throw new RuntimeException('Confirma que contrastaste el resultado con el proveedor.');
            $service->reconcile($lead,(string)($_POST['operation']??''),(string)($_POST['outcome']??''),(string)($_POST['reference']??''),(string)($_POST['note']??''),$actor);
            header('Location: responder-solicitud.php?'.http_build_query(['lead'=>$lead,'operation'=>$_POST['operation']??'']),true,303);exit;
        }elseif($action==='send'){
            if(($_POST['confirm']??'')!=='1')throw new RuntimeException('Confirma el destinatario y esta versión del mensaje.');
            $client=new BrevoTransactionalClient($settings,$simulated?static fn(array $payload):array=>['status'=>201,'body'=>['messageId'=>'mock-'.bin2hex(random_bytes(8))]]:null);
            $result=$service->send($lead,(string)($_POST['operation']??''),(string)($_POST['content_hash']??''),$settings,$actor,$client);
            $_SESSION['lead_reply_notice']=$simulated?'Simulación registrada. No se envió ningún correo real.':'Resultado registrado: '.(['accepted'=>'aceptado por el proveedor; no confirma entrega','failed'=>'rechazado por el proveedor','uncertain'=>'resultado incierto; no repetir sin reconciliar','sending'=>'en proceso o pendiente de reconciliar'][$result]??$result);
            header('Location: responder-solicitud.php?'.http_build_query(['lead'=>$lead,'operation'=>$_POST['operation']??'']),true,303);exit;
        }else throw new RuntimeException('Acción no válida.');
    }
    $history=$service->history($lead);
}catch(Throwable $e){if(class_exists('PortalIncidents',false))PortalIncidents::technical($e,'respuesta_individual');$error=$e instanceof PDOException?'No se pudo cargar la respuesta. Revisa la migración 048.':$e->getMessage();http_response_code(400);}
$notice=(string)($_SESSION['lead_reply_notice']??'');unset($_SESSION['lead_reply_notice']);
$labels=['draft'=>'Borrador','sending'=>'En proceso · no repetir sin reconciliar','accepted'=>'Aceptado por el proveedor · entrega no confirmada','failed'=>'Rechazado por el proveedor','uncertain'=>'Incierto · requiere reconciliación'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Responder solicitud | Administración</title><?php require __DIR__.'/_theme.php'; ?></head><body class="portal-admin"><main class="wrap admin-page"><h1>Responder a <?=esc($request['business'])?></h1><p><a href="solicitud-detalle.php?type=lead&amp;id=<?=esc($lead)?>">← Revisar solicitud</a></p><?php require __DIR__.'/_navigation.php'; ?><?php if($simulated):?><p class="notice">Entorno de pruebas: transporte simulado. Nunca se envían mensajes reales desde esta pantalla local.</p><?php endif ?><?php if($error):?><p role="alert" class="notice"><?=esc($error)?></p><?php endif ?><?php if($notice):?><p role="status" class="notice"><?=esc($notice)?></p><?php endif ?><p>Solicita contacto: <?=$request['wants_contact']?'Sí':'No'?> · Consentimiento registrado: <?=esc($request['consent_version'])?>. Responder no modifica el estado de la solicitud ni incorpora a campañas.</p>
<?php if(!$row||$row['status']==='draft'):?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="prepare"><input type="hidden" name="operation" value="<?=esc($row['id']??'')?>"><label>Destinatario<input type="email" name="recipient" maxlength="254" required value="<?=esc($row['recipient']??$request['email'])?>"></label><label>Asunto<input name="subject" maxlength="200" required value="<?=esc($row['subject']??'Tu negocio en Explorando Lugares')?>"></label><label>Mensaje<textarea name="message" rows="6" maxlength="5000" required><?=esc($row['message_text']??'Gracias por escribirnos. Puedes comparar las suscripciones y gestionar tu negocio desde tu cuenta personal. Si necesitas ayuda, responde a este correo.')?></textarea></label><?php if(!$row&&$history):?><label class="admin-checkbox-field"><input type="checkbox" name="new_reply_confirm" value="1" required><span>Revisé el historial y quiero preparar una respuesta adicional</span></label><?php endif ?><button class="pill">Guardar borrador y revisar</button></form><?php endif ?>
<?php if($row):?><section class="card"><h2>Vista previa de la versión guardada</h2><dl><dt>Destinatario</dt><dd><?=esc($row['recipient'])?></dd><dt>Remitente</dt><dd><?=esc($row['sender_name'])?> · <?=esc($row['sender_email'])?></dd><dt>Las respuestas llegan a</dt><dd><?=esc($row['reply_to'])?></dd><dt>Asunto</dt><dd><?=esc($row['subject'])?></dd><dt>Estado</dt><dd><?=esc($labels[$row['status']])?></dd></dl><iframe title="Vista previa del correo" sandbox="" referrerpolicy="no-referrer" src="respuesta-vista-previa.php?lead=<?=esc($lead)?>&amp;operation=<?=esc($row['id'])?>" class="admin-reply-preview"></iframe><details><summary>Versión de texto</summary><pre class="admin-reply-text"><?=esc($row['text_body'])?></pre></details><?php if($row['status']==='draft'):?><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="send"><input type="hidden" name="operation" value="<?=esc($row['id'])?>"><input type="hidden" name="content_hash" value="<?=esc($row['content_hash'])?>"><label class="admin-checkbox-field"><input type="checkbox" name="confirm" value="1" required><span>Confirmo este destinatario, remitente, asunto y contenido</span></label><button class="pill"><?=$simulated?'Confirmar simulación de esta respuesta':'Confirmar y enviar esta respuesta'?></button></form><?php elseif(in_array($row['status'],['sending','uncertain'],true)):?><p class="notice">No se permite repetir esta operación. Revisa su identificador con el proveedor: <?=esc($row['id'])?>. Si ya fue aceptada, no generes otra respuesta para reintentar.</p><?php endif ?><?php if(in_array($row['status'],['sending','uncertain'],true)):?><details><summary>Registrar reconciliación con el proveedor</summary><p>Consulta primero los registros de Brevo. No deduzcas el resultado por ausencia de un correo en la bandeja del destinatario. Esta acción no envía mensajes.</p><form method="post" class="registration-form"><input type="hidden" name="csrf" value="<?=esc($_SESSION['csrf'])?>"><input type="hidden" name="action" value="reconcile"><input type="hidden" name="operation" value="<?=esc($row['id'])?>"><label>Resultado comprobado<select name="outcome" required><option value="">Selecciona</option><option value="accepted">Brevo confirmó aceptación</option><option value="failed">Brevo confirmó que no fue aceptado</option></select></label><label>Identificador o referencia de soporte del proveedor<input name="reference" minlength="5" maxlength="500" required></label><label>Evidencia y explicación<textarea name="note" minlength="30" maxlength="2000" rows="4" required></textarea></label><label class="admin-checkbox-field"><input type="checkbox" name="confirm_reconcile" value="1" required><span>Contrasté este resultado con el proveedor</span></label><button class="pill">Guardar reconciliación sin enviar</button></form></details><?php endif ?><?php if(!empty($row['reconciled_at'])):?><p>Reconciliada el <?=esc($row['reconciled_at'])?> por <?=esc($row['reconciled_by'])?>: <?=esc($row['reconciliation_note'])?></p><?php endif ?></section><?php endif ?>
<section><h2>Historial de respuestas individuales</h2><?php if(!$history):?><p>Todavía no hay respuestas.</p><?php endif ?><?php foreach($history as $entry):?><p><a href="?lead=<?=esc($lead)?>&amp;operation=<?=esc($entry['id'])?>"><?=esc($entry['subject'])?></a> · <?=esc($labels[$entry['status']])?> · <?=esc($entry['created_at'])?></p><?php endforeach ?><?php if($row):?><p><a href="?lead=<?=esc($lead)?>">Preparar otra respuesta (revisar historial primero)</a></p><?php endif ?></section></main></body></html>
